from pathlib import Path
import base64, hashlib, re, shutil

DATA = base64.b64decode("""[... ELLIPSIZATION ...]""")
EXPECTED = hashlib.sha256(DATA).hexdigest()

root = Path("video-compressor/app/src/main")
res = root / "res"

# Remove every previous launcher/adaptive icon so Android cannot fall back to the robot.
for p in [
    res / "mipmap-anydpi-v26" / "ic_launcher.xml",
    res / "mipmap-anydpi-v26" / "ic_launcher_round.xml",
    res / "drawable" / "ic_launcher_foreground.xml",
    res / "drawable" / "ic_launcher_background.xml",
]:
    if p.exists():
        p.unlink()

for density in ["mdpi", "hdpi", "xhdpi", "xxhdpi", "xxxhdpi"]:
    d = res / f"mipmap-{density}"
    d.mkdir(parents=True, exist_ok=True)
    for old in d.glob("ic_launcher*"):
        old.unlink()
    (d / "ic_launcher.jpg").write_bytes(DATA)
    (d / "ic_launcher_round.jpg").write_bytes(DATA)

manifest = root / "AndroidManifest.xml"
text = manifest.read_text(encoding="utf-8")
text = re.sub(r'android:icon="[^"]+"', 'android:icon="@mipmap/ic_launcher"', text)
if 'android:roundIcon=' in text:
    text = re.sub(r'android:roundIcon="[^"]+"', 'android:roundIcon="@mipmap/ic_launcher_round"', text)
else:
    text = text.replace('android:icon="@mipmap/ic_launcher"', 'android:icon="@mipmap/ic_launcher"\n        android:roundIcon="@mipmap/ic_launcher_round"')
manifest.write_text(text, encoding="utf-8")

print("Installed v2.3 pixel launcher artwork:", EXPECTED)
